#!/usr/bin/env python3
"""Expands Kubernetes-style OWNERS_ALIASES into directory OWNERS files.

cncf/prow-github-actions v3.5.0 ignores OWNERS_ALIASES (`Not read`). This tool
lets maintainers define groups in OWNERS_ALIASES and reference them inside
OWNERS.in files across the tree, compiling flat GitHub handles into sibling
OWNERS files and verifying zero drift in CI.
"""

from __future__ import annotations

import argparse
from pathlib import Path
import sys


HEADER = (
    "# Code generated by tools/ownersgen.py from OWNERS.in and OWNERS_ALIASES;"
    " DO NOT EDIT.\n"
)


def strip_comment(line: str) -> str:
    in_single = False
    in_double = False
    for idx, ch in enumerate(line):
        if ch == "'" and not in_double:
            in_single = not in_single
        elif ch == '"' and not in_single:
            in_double = not in_double
        elif ch == "#" and not in_single and not in_double:
            return line[:idx]
    return line


def clean_scalar(raw: str) -> str:
    val = raw.strip()
    if len(val) >= 2 and val[0] == val[-1] and val[0] in ("'", '"'):
        return val[1:-1].strip()
    return val


def parse_owners_aliases(text: str) -> dict[str, list[str]]:
    aliases: dict[str, list[str]] = {}
    in_aliases = False
    current_group: str | None = None

    for lineno, raw_line in enumerate(text.splitlines(), start=1):
        line = strip_comment(raw_line).rstrip()
        if not line.strip():
            continue
        indent = len(line) - len(line.lstrip(" "))
        stripped = line.strip()

        if indent == 0:
            if stripped == "aliases:":
                in_aliases = True
                current_group = None
                continue
            raise ValueError(f"OWNERS_ALIASES:{lineno}: unexpected top-level line: {stripped}")

        if not in_aliases:
            raise ValueError(f"OWNERS_ALIASES:{lineno}: expected 'aliases:' block")

        if not stripped.startswith("-") and stripped.endswith(":"):
            group = clean_scalar(stripped[:-1])
            if not group:
                raise ValueError(f"OWNERS_ALIASES:{lineno}: empty alias name")
            aliases[group] = []
            current_group = group
            continue

        if stripped.startswith("-"):
            if current_group is None:
                raise ValueError(f"OWNERS_ALIASES:{lineno}: list item outside alias group")
            member = clean_scalar(stripped[1:])
            if not member:
                raise ValueError(f"OWNERS_ALIASES:{lineno}: empty member in {current_group}")
            aliases[current_group].append(member)
            continue

        raise ValueError(f"OWNERS_ALIASES:{lineno}: unsupported syntax: {stripped}")

    return aliases


def resolve_group_or_user(
    token: str, aliases: dict[str, list[str]], stack: tuple[str, ...] = ()
) -> list[str]:
    if token not in aliases:
        return [token]
    if token in stack:
        cycle = " -> ".join((*stack, token))
        raise ValueError(f"cycle detected in OWNERS_ALIASES: {cycle}")
    expanded: list[str] = []
    for item in aliases[token]:
        expanded.extend(resolve_group_or_user(item, aliases, (*stack, token)))
    return expanded


def dedupe_preserve_order(items: list[str]) -> list[str]:
    seen: set[str] = set()
    out: list[str] = []
    for item in items:
        key = item.lower()
        if key not in seen:
            seen.add(key)
            out.append(item)
    return out


def parse_owners_in(text: str, source: Path) -> dict[str, object]:
    no_parent_owners = False
    lists: dict[str, list[str]] = {
        "approvers": [],
        "reviewers": [],
        "labels": [],
    }
    section: str | None = None

    for lineno, raw_line in enumerate(text.splitlines(), start=1):
        line = strip_comment(raw_line).rstrip()
        if not line.strip():
            continue
        indent = len(line) - len(line.lstrip(" "))
        stripped = line.strip()

        if indent == 0 and stripped.endswith(":"):
            key = stripped[:-1].strip()
            if key not in ("options", "approvers", "reviewers", "labels"):
                raise ValueError(f"{source}:{lineno}: unsupported section '{key}'")
            section = key
            continue

        if section == "options":
            if ":" not in stripped:
                raise ValueError(f"{source}:{lineno}: invalid options entry '{stripped}'")
            opt_k, opt_v = [part.strip() for part in stripped.split(":", 1)]
            if opt_k != "no_parent_owners":
                raise ValueError(f"{source}:{lineno}: unsupported option '{opt_k}'")
            if opt_v.lower() == "true":
                no_parent_owners = True
            elif opt_v.lower() == "false":
                no_parent_owners = False
            else:
                raise ValueError(f"{source}:{lineno}: boolean expected for no_parent_owners")
            continue

        if section in lists and stripped.startswith("-"):
            entry = clean_scalar(stripped[1:])
            if not entry:
                raise ValueError(f"{source}:{lineno}: empty list entry in {section}")
            lists[section].append(entry)
            continue

        raise ValueError(f"{source}:{lineno}: unsupported syntax '{stripped}'")

    return {
        "no_parent_owners": no_parent_owners,
        "approvers": lists["approvers"],
        "reviewers": lists["reviewers"],
        "labels": lists["labels"],
    }


def render_owners(parsed: dict[str, object], aliases: dict[str, list[str]]) -> str:
    out: list[str] = [HEADER]
    if parsed["no_parent_owners"]:
        out.append("options:\n  no_parent_owners: true\n")

    for field in ("approvers", "reviewers"):
        raw_items: list[str] = parsed[field]  # type: ignore[assignment]
        expanded: list[str] = []
        for token in raw_items:
            expanded.extend(resolve_group_or_user(token, aliases))
        final_items = dedupe_preserve_order(expanded)
        if final_items:
            out.append(f"{field}:\n")
            for user in final_items:
                if user.startswith("@"):
                    out.append(f"  - '{user}'\n")
                else:
                    out.append(f"  - {user}\n")

    labels: list[str] = dedupe_preserve_order(parsed["labels"])  # type: ignore[arg-type]
    if labels:
        out.append("labels:\n")
        for label in labels:
            out.append(f"  - {label}\n")

    return "".join(out)


def run(repo_root: Path, check_only: bool) -> int:
    for forbidden in (repo_root / "CODEOWNERS", repo_root / ".github" / "CODEOWNERS"):
        if forbidden.exists():
            print(
                f"ERROR: {forbidden.relative_to(repo_root)} exists; leave GitHub"
                " CODEOWNERS off when using prow-github-actions OWNERS.",
                file=sys.stderr,
            )
            return 1

    aliases_path = repo_root / "OWNERS_ALIASES"
    if not aliases_path.exists():
        print("ERROR: OWNERS_ALIASES not found at repository root", file=sys.stderr)
        return 1

    aliases = parse_owners_aliases(aliases_path.read_text(encoding="utf-8"))
    owners_in_files = sorted(
        p for p in repo_root.rglob("OWNERS.in") if ".git" not in p.parts
    )
    if not owners_in_files:
        print("ERROR: no OWNERS.in files found", file=sys.stderr)
        return 1

    stale: list[Path] = []
    for src in owners_in_files:
        parsed = parse_owners_in(src.read_text(encoding="utf-8"), src)
        rendered = render_owners(parsed, aliases)
        target = src.with_name("OWNERS")
        if check_only:
            if not target.exists() or target.read_text(encoding="utf-8") != rendered:
                stale.append(target.relative_to(repo_root))
        else:
            target.write_text(rendered, encoding="utf-8")

    if stale:
        print(
            "ERROR: out-of-date OWNERS files (run ./hack/update-owners.sh):",
            file=sys.stderr,
        )
        for rel in stale:
            print(f"  - {rel}", file=sys.stderr)
        return 1

    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--root",
        type=Path,
        default=Path(__file__).resolve().parents[1],
        help="Repository root directory",
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="Verify generated OWNERS files match OWNERS.in + OWNERS_ALIASES",
    )
    args = parser.parse_args()
    return run(args.root.resolve(), args.check)


if __name__ == "__main__":
    raise SystemExit(main())
